const body=$input.first().json.body;
if(!body || typeof body!=='object' || Array.isArray(body))throw new Error('legacy_invalid_body');
const modern=["company_id", "companyId", "schema_version", "schemaVersion", "cycle_id", "cycleId", "content_revision", "contentRevision", "account_id", "accountId", "account_name", "accountName", "planner_kind", "plannerKind", "format", "scheduled_local", "scheduled_utc", "qc_state", "preview_url", "remote_url", "asset", "row_key", "rowKey"];
if(Object.keys(body).some(k=>k!=='sheetId'&&k!=='row'))throw new Error('legacy_identity_or_unknown_fields_rejected');
if(typeof body.sheetId!=='string'||!/^[A-Za-z0-9_-]{1,200}$/.test(body.sheetId))throw new Error('legacy_invalid_sheet_id');
const row=body.row;
if(!row || typeof row!=='object'||Array.isArray(row))throw new Error('legacy_invalid_row');
if(modern.some(k=>Object.prototype.hasOwnProperty.call(row,k)))throw new Error('legacy_identity_fields_rejected');
const aliases=[["Week Of", "weekOf"], ["Theme of the Week", "theme"], ["Research", "research"], ["Core Content", "coreContent", "title"], ["Images", "images"], ["Videos", "videos"], ["Facebook", "facebook"], ["Instagram", "instagram"], ["LinkedIn", "linkedin"], ["YouTube", "youtube"], ["TikTok", "tiktok"], ["Pinterest", "pinterest"], ["Carousels", "carousels"], ["Blog", "blog"], ["Podcast", "podcast"], ["Email", "email"], ["QC", "qc"], ["Scheduled", "scheduled", "date"], ["Overall", "overall", "status"], ["Notes", "notes"]];
const allowed=new Set(aliases.flat().concat(['platform']));
if(Object.keys(row).some(k=>!allowed.has(k)))throw new Error('legacy_unknown_row_fields_rejected');
for(const value of Object.values(row)){
 if(value!==null && !['string','number','boolean'].includes(typeof value))throw new Error('legacy_non_scalar_cell');
 if(typeof value==='number'&&!Number.isFinite(value))throw new Error('legacy_non_finite_cell');
 if(typeof value==='string'&&value.length>50000)throw new Error('legacy_cell_too_large');
}
if(JSON.stringify(row).length>250000)throw new Error('legacy_row_too_large');
const values=aliases.map(keys=>{for(const key of keys)if(row[key]!==undefined&&row[key]!==null&&row[key]!=='')return row[key];return '';});
if(!values.some(v=>v!==''))throw new Error('legacy_empty_row');
const warnings=Object.prototype.hasOwnProperty.call(row,'platform')?['Generic platform was not mapped into TikTok or another platform column; use an explicit platform column.']:[];
return [{json:{sheetId:body.sheetId,values,warnings}}];

const src=$('Validate Legacy Input').first().json;
const file=$input.first().json;
if(file.id!==src.sheetId || file.mimeType!=='application/vnd.google-apps.spreadsheet' || file.trashed!==false)throw new Error('legacy_document_not_verified');
return [{json:{verified:true}}];

const data=$input.first().json;
if(!Array.isArray(data.permissions)||data.nextPageToken)throw new Error('legacy_permission_readback_incomplete');
const now=Date.now();
const allowed=data.permissions.some(p=>{
 if(p.type!=='anyone'||p.role!=='writer'||p.deleted===true)return false;
 if(p.expirationTime!==undefined&&p.expirationTime!==null){
  const expiry=typeof p.expirationTime==='string'?Date.parse(p.expirationTime):NaN;
  if(!Number.isFinite(expiry)||expiry<=now)return false;
 }
 return true;
});
if(!allowed)throw new Error('legacy_public_edit_capability_missing');
return [{json:{verified:true}}];

const src=$('Validate Legacy Input').first().json;
const metadata=$input.first().json;
if(metadata.spreadsheetId!==src.sheetId||!Array.isArray(metadata.sheets))throw new Error('legacy_sheet_metadata_mismatch');
const tabs=metadata.sheets.filter(s=>s.properties?.title==='Weekly Overview');
if(tabs.length!==1||!Number.isInteger(tabs[0].properties.sheetId)||tabs[0].properties.sheetId<0)throw new Error('legacy_weekly_overview_missing');
return [{json:{verified:true}}];

const data=$input.first().json;
const expected=["Week Of", "Theme of the Week", "Research", "Core Content", "Images", "Videos", "Facebook", "Instagram", "LinkedIn", "YouTube", "TikTok", "Pinterest", "Carousels", "Blog", "Podcast", "Email", "QC", "Scheduled", "Overall", "Notes"];
if(!Array.isArray(data.values)||data.values.length>10)throw new Error('legacy_headers_require_preserving_repair');
const matches=data.values.flatMap((row,index)=>JSON.stringify(row)===JSON.stringify(expected)?[index+1]:[]);
if(matches.length!==1)throw new Error('legacy_headers_require_preserving_repair');
return [{json:{...$('Validate Legacy Input').first().json,headerRow:matches[0]}}];

const src=$('Validate Legacy Headers').first().json;
const response=$input.first().json;
const range=response.updates?.updatedRange;
const match=typeof range==='string'?range.match(/^'?Weekly Overview'?!A(\d+):T(\d+)$/):null;
if(response.spreadsheetId!==src.sheetId || !match || Number(match[1])<=src.headerRow || match[1]!==match[2] || response.updates.updatedRows!==1)throw new Error('legacy_append_receipt_unverified_reconcile_before_retry');
return [{json:{success:true,sheetId:src.sheetId,updatedRange:range,legacy_overview_only:true,publication_verified:false,company_ownership_claimed:false,warnings:src.warnings}}];
